    }

    // 获取设置，备用书源使用旧版设置，书源从缓存获取设置
    if (isBackupSource()) {
        settings = JSON.parse(String(source.variableComment).match(RegExp(/{([\s\S]*?)}/gm)))
    } else {
        // cache.delete("pixivSettings")
        settings = getFromCache("pixivSettings")
    }
    if (settings !== null) {
        java.log("⚙️ 使用自定义设置")
    } else {
        settings = {}
        settings.SEARCH_AUTHOR = true       // 搜索：默认搜索作者名称
