    if (!key) key = Object.keys(maxPagesName)[0]
    let maxPages = getFromCache(key)
    if (!maxPages) maxPages = 1
    if (method.includes("add")) maxPages += 1
    if (method.includes("min")) maxPages -= 1

    if (maxPages <= 1) {
        maxPages = 1
        msg += "⚠️ 搜索页码不能再减小了\n"
    }
    if (maxPages >= 3) {
        msg += "⚠️ 搜索页码越多，搜索速度越慢\n"
    }
    if (maxPages >= 10) {
