            novels = novels.filter(novel => !watchedSeries.includes(Number(novel.seriesId)))
            novels2 = novels.map(novel => novel.id)
            if (novels1.length >= 1) novels0 = novels1
            java.log(`⏬ 过滤追更：过滤前${novels0.length}；过滤后${novels2.length}`)
